-- Draft in-place retune of the six earlier dungeon conversions. Affixes and effects follow separately.
CREATE TEMPORARY TABLE `_coa_tbc_existing_gear` (
    `source` INT UNSIGNED NOT NULL,
    `target` INT UNSIGNED PRIMARY KEY,
    `Quality` INT NOT NULL,
    `ItemLevel` INT NOT NULL,
    `RequiredLevel` INT NOT NULL,
    `armor` INT NOT NULL,
    `block` INT NOT NULL,
    `socketBonus` INT NOT NULL,
    `stat_value1` INT NOT NULL,
    `stat_value2` INT NOT NULL,
    `stat_value3` INT NOT NULL,
    `stat_value4` INT NOT NULL,
    `stat_value5` INT NOT NULL,
    `stat_value6` INT NOT NULL,
    `stat_value7` INT NOT NULL,
    `stat_value8` INT NOT NULL,
    `stat_value9` INT NOT NULL,
    `stat_value10` INT NOT NULL,
    `holy_res` INT NOT NULL,
    `fire_res` INT NOT NULL,
    `nature_res` INT NOT NULL,
    `frost_res` INT NOT NULL,
    `shadow_res` INT NOT NULL,
    `arcane_res` INT NOT NULL,
    `dmg_min1` DECIMAL(12,3) NOT NULL,
    `dmg_max1` DECIMAL(12,3) NOT NULL,
    `dmg_min2` DECIMAL(12,3) NOT NULL,
    `dmg_max2` DECIMAL(12,3) NOT NULL,
    `spellid_1` INT NOT NULL,
    `spellid_2` INT NOT NULL,
    `spellid_3` INT NOT NULL,
    `spellid_4` INT NOT NULL,
    `spellid_5` INT NOT NULL,
    `spelltrigger_1` INT NOT NULL,
    `spelltrigger_2` INT NOT NULL,
    `spelltrigger_3` INT NOT NULL,
    `spelltrigger_4` INT NOT NULL,
    `spelltrigger_5` INT NOT NULL
) ENGINE=InnoDB;

DELETE FROM `_coa_tbc_existing_gear`;

UPDATE `item_template` AS `item` JOIN `_coa_tbc_existing_gear` AS `budget` ON `item`.`entry` = `budget`.`target`
SET `item`.`Quality` = `budget`.`Quality`,
    `item`.`ItemLevel` = `budget`.`ItemLevel`,
    `item`.`RequiredLevel` = `budget`.`RequiredLevel`,
    `item`.`armor` = `budget`.`armor`,
    `item`.`block` = `budget`.`block`,
    `item`.`socketBonus` = `budget`.`socketBonus`,
    `item`.`stat_value1` = `budget`.`stat_value1`,
    `item`.`stat_value2` = `budget`.`stat_value2`,
    `item`.`stat_value3` = `budget`.`stat_value3`,
    `item`.`stat_value4` = `budget`.`stat_value4`,
    `item`.`stat_value5` = `budget`.`stat_value5`,
    `item`.`stat_value6` = `budget`.`stat_value6`,
    `item`.`stat_value7` = `budget`.`stat_value7`,
    `item`.`stat_value8` = `budget`.`stat_value8`,
    `item`.`stat_value9` = `budget`.`stat_value9`,
    `item`.`stat_value10` = `budget`.`stat_value10`,
    `item`.`holy_res` = `budget`.`holy_res`,
    `item`.`fire_res` = `budget`.`fire_res`,
    `item`.`nature_res` = `budget`.`nature_res`,
    `item`.`frost_res` = `budget`.`frost_res`,
    `item`.`shadow_res` = `budget`.`shadow_res`,
    `item`.`arcane_res` = `budget`.`arcane_res`,
    `item`.`dmg_min1` = `budget`.`dmg_min1`,
    `item`.`dmg_max1` = `budget`.`dmg_max1`,
    `item`.`dmg_min2` = `budget`.`dmg_min2`,
    `item`.`dmg_max2` = `budget`.`dmg_max2`,
    `item`.`spellid_1` = `budget`.`spellid_1`,
    `item`.`spellid_2` = `budget`.`spellid_2`,
    `item`.`spellid_3` = `budget`.`spellid_3`,
    `item`.`spellid_4` = `budget`.`spellid_4`,
    `item`.`spellid_5` = `budget`.`spellid_5`,
    `item`.`spelltrigger_1` = `budget`.`spelltrigger_1`,
    `item`.`spelltrigger_2` = `budget`.`spelltrigger_2`,
    `item`.`spelltrigger_3` = `budget`.`spelltrigger_3`,
    `item`.`spelltrigger_4` = `budget`.`spelltrigger_4`,
    `item`.`spelltrigger_5` = `budget`.`spelltrigger_5`;

DELETE FROM `coa_dungeon_rescale_item` WHERE `entry` IN (SELECT `target` FROM `_coa_tbc_existing_gear`);

DROP TEMPORARY TABLE `_coa_tbc_existing_gear`;
